public static GUPRebateAgreementType findByRebateTypeAndCompany(GUPRebateAgreementTypeName _rebateType, CompanyId _companyId = curExt(), boolean _forUpdate = false)
{
    GUPRebateAgreementType rebateAgreementType;

    select firstonly rebateAgreementType
        where rebateAgreementType.TypeName == _rebateType
            && rebateAgreementType.DataAreaId == _companyId;

    if(rebateAgreementType.RecId && _forUpdate)
    {
        rebateAgreementType.selectForUpdate(_forUpdate);
    }

    return rebateAgreementType;
}
